package dev.arabicgames.phone;
import java.util.*;import java.util.regex.*;
/** Safe lexical forms only. Dialect is not a reason to hide or skip a sentence. */
final class FormalArabic {
 private static final Map<String,String> NAMES=new LinkedHashMap<>();static{String[] en={"Jason","Lucia","Local","Locals","Tourist","Tourists","Driver","Stranger","Karim","Raul","Wade","Kenton","Andy","Brian","Billy","Vicki","Kyle","Dook"};String[] ar={"جيسون","لوسيا","أحد السكان","السكان","السائح","السياح","السائق","الغريب","كريم","راؤول","وايد","كينتون","آندي","براين","بيلي","فيكي","كايل","دوك"};for(int i=0;i<en.length;i++)NAMES.put(en[i].toLowerCase(Locale.ROOT),ar[i]);}
 static String ready(String source){String text=source.trim();String name=NAMES.get(text.toLowerCase(Locale.ROOT));if(name!=null)return name;String label="",body=text;int colon=text.indexOf(':');if(colon>0&&colon<40){label=NAMES.get(text.substring(0,colon).trim().toLowerCase(Locale.ROOT));if(label==null)return null;body=text.substring(colon+1).trim();}String key=body.toLowerCase(Locale.ROOT).replace('’','\'');if(key.equals("suck my fuckin' nuts!")||key.equals("suck my fucking nuts!")||key.equals("suck my balls!"))return (label.isEmpty()?"":label+": ")+"تبًّا لك، أيها الوغد!";return null;}
 static boolean needsRephrase(String source,String translated){String value=normalize(translated);if(source.matches("(?s).*\\bMo\\b.*"))value=value.replaceAll("(?<![\\p{L}])مو(?![\\p{L}])","");return Pattern.compile("(?<![\\p{L}])(?:عايز|عاوز|عايزة|عاوزة|عشان|علشان|اللي|مو|مش|لسه|لسّا|هالشي|هالأمر|دحين|دلوقتي)(?![\\p{L}])").matcher(value).find();}
 static String normalize(String text){if(text==null)return "";text=text.replaceAll("(?<![\\p{L}])(ال)?(?:قحب[ةه]|شرموط[ةه])(?![\\p{L}])","$1عاهرة").replaceAll("(?<![\\p{L}])(ال)?(?:قحاب|شراميط)(?![\\p{L}])","$1عاهرات");Map<String,String> variants=new LinkedHashMap<>();variants.put("هذي","هذه");variants.put("هاذي","هذه");variants.put("هاذا","هذا");variants.put("هذول","هؤلاء");variants.put("هذولا","هؤلاء");variants.put("إيش","ماذا");variants.put("ايش","ماذا");variants.put("وش","ماذا");variants.put("تبغى","تريد");variants.put("تبي","تريد");variants.put("أبغى","أريد");variants.put("ابغى","أريد");for(Map.Entry<String,String> term:variants.entrySet())text=text.replaceAll("(?<![\\p{L}])"+Pattern.quote(term.getKey())+"(?![\\p{L}])",term.getValue());return text;}
}
